#!/usr/bin/env bash
# ==============================================================================
# Itarang Phase 4 — Standalone dashboard
# Run as root on the Hostinger VPS.
#
# What this does:
#   1. Drops dashboard/{Dockerfile,dashboard_state.php,index.html} into
#      /opt/intellicar/storage/dashboard/  (md5-verified)
#   2. Idempotently appends a 'dashboard' service block to docker-compose.yml
#      (skipped if already present)
#   3. Builds and starts the dashboard container, bound to 127.0.0.1:8090
#   4. Smoke-tests /op=fleet_state from inside the container
#   5. Prints the SSH-tunnel command to view it from your laptop
#
# Idempotent: re-running just refreshes files and rebuilds the container.
# ==============================================================================
set -euo pipefail

STORAGE_DIR=/opt/intellicar/storage
DASH_DIR="$STORAGE_DIR/dashboard"
COMPOSE="$STORAGE_DIR/docker-compose.yml"

cd "$STORAGE_DIR"

echo "==> [1/5] Writing dashboard files (md5-verified)"
mkdir -p "$DASH_DIR"

extract_b64() {
  local target="$1"; local expected="$2"; local b64="$3"
  echo "$b64" | base64 -d > "$target"
  local actual=$(md5sum "$target" | awk '{print $1}')
  if [ "$actual" != "$expected" ]; then
    echo "    ERROR: md5 mismatch for $target. expected=$expected actual=$actual"
    exit 1
  fi
  echo "    $target ($(wc -c < $target) bytes, md5 ok)"
}

extract_b64 "$DASH_DIR/Dockerfile"          "0e860ac6a7ff8df73388c1c73bd32601" ""
extract_b64 "$DASH_DIR/dashboard_state.php" "178e38b2292c1639223343171a306db6"        ""
extract_b64 "$DASH_DIR/index.html"          "6c1404bac357c178839d33ead4bd4db6"       ""

echo "==> [2/5] Patching docker-compose.yml"
if grep -qE '^[[:space:]]*dashboard:' "$COMPOSE"; then
    echo "    dashboard service already present — leaving compose file alone"
else
    cp "$COMPOSE" "$COMPOSE.bak.$(date +%s)"
    # Insert before "volumes:" if present, else append at end
    if grep -qE '^volumes:' "$COMPOSE"; then
        # Insert the dashboard service block above the top-level "volumes:" key
        awk '
          /^volumes:/ && !done {
            print "  dashboard:";
            print "    build: ./dashboard";
            print "    container_name: itarang_dashboard";
            print "    restart: unless-stopped";
            print "    depends_on:";
            print "      postgres:";
            print "        condition: service_healthy";
            print "      redis:";
            print "        condition: service_healthy";
            print "    environment:";
            print "      REDIS_HOST: redis";
            print "      REDIS_PORT: 6379";
            print "      PG_DSN_HOST: \"pgsql:host=postgres;port=5432;dbname=intellicar\"";
            print "      PG_USER: dashboard_ro";
            print "      PG_PASS: CHANGEME_dashboard_ro";
            print "      INTELLICAR_BASE: \"https://apiplatform.intellicar.in/api/standard\"";
            print "    ports:";
            print "      - \"127.0.0.1:8090:80\"";
            print "    logging:";
            print "      driver: \"json-file\"";
            print "      options:";
            print "        max-size: \"10m\"";
            print "        max-file: \"3\"";
            print "";
            done = 1;
          }
          { print }
        ' "$COMPOSE" > "$COMPOSE.new"
        mv "$COMPOSE.new" "$COMPOSE"
    else
        cat >> "$COMPOSE" <<'YAML_EOF'

  dashboard:
    build: ./dashboard
    container_name: itarang_dashboard
    restart: unless-stopped
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy
    environment:
      REDIS_HOST: redis
      REDIS_PORT: 6379
      PG_DSN_HOST: "pgsql:host=postgres;port=5432;dbname=intellicar"
      PG_USER: dashboard_ro
      PG_PASS: CHANGEME_dashboard_ro
      INTELLICAR_BASE: "https://apiplatform.intellicar.in/api/standard"
    ports:
      - "127.0.0.1:8090:80"
    logging:
      driver: "json-file"
      options:
        max-size: "10m"
        max-file: "3"
YAML_EOF
    fi
    echo "    dashboard service inserted (backup saved)"
fi

# Sanity check the YAML
if ! docker compose config -q 2>/dev/null; then
    echo "    ERROR: docker compose config -q failed. Restoring backup."
    cp "$(ls -t $COMPOSE.bak.* | head -1)" "$COMPOSE"
    exit 1
fi

echo "==> [3/5] Building and starting dashboard container"
docker compose build dashboard
docker compose up -d dashboard
docker compose ps dashboard

echo "==> [4/5] Smoke-testing endpoints"
sleep 3
echo "    /op=fleet_state (first 200 chars):"
docker compose exec -T dashboard curl -sf "http://localhost/dashboard_state.php?op=fleet_state"     | head -c 200 || echo "    [smoke test failed]"
echo ""
echo "    index.html served?"
docker compose exec -T dashboard curl -sf -o /dev/null -w "    HTTP %{http_code}\n"     "http://localhost/" || echo "    [index test failed]"

echo ""
echo "================================================================="
echo " Phase 4 dashboard complete."
echo ""
echo " From your Mac, open an SSH tunnel and visit it:"
echo ""
echo "   ssh -L 8090:127.0.0.1:8090 root@72.61.246.37"
echo ""
echo " Then in your browser: http://localhost:8090"
echo ""
echo " The tunnel only forwards while your SSH session is open."
echo " To take it down later:  docker compose down dashboard"
echo "================================================================="
